-- Local synthetic fixture only. Never run on hosted data; no provider request is made.
begin;
create temporary table ex(owner_id uuid,outsider uuid,w uuid,s uuid,profile uuid,test_run uuid,coordinator uuid,content uuid,quality uuid,r1 uuid,c1 uuid,g1 uuid,r2 uuid,c2 uuid,g2 uuid,r3 uuid,c3 uuid,g3 uuid,claim1 uuid,claim2 uuid,claim3 uuid);
insert into ex values(gen_random_uuid(),gen_random_uuid(),null,null,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into auth.users(id) select owner_id from ex union all select outsider from ex;
create function pg_temp.exexpect(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;else raise exception 'Unexpected: %',sqlerrm;end if;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,anon,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;
grant all on ex to authenticated,anon,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from ex),true);
update ex set w=(select id from public.bz_create_workspace('Execution task fixture'));
update ex set s=(select id from public.bz_register_site(w,'Execution fixture','external','business','https://execution-fixture.com/',null,'active',true));
select public.bz_save_site_agent_preferences(w,s,'{"brandVoice":"practical","audience":"small business owners","guidance":"Private drafts only"}',0) from ex;
select public.bz_mutate_knowledge(w,s,gen_random_uuid(),'save','{"title":"Approved facts","filename":"facts.md","sourceText":"Bizoveya prepares private reviewable drafts.","facts":[{"id":"f1","text":"Bizoveya prepares private reviewable drafts."}]}',0) from ex;
select public.bz_mutate_knowledge(w,s,(select id from public.bizoveya_knowledge_sources where site_id=s),'approve',null,1) from ex;
reset role;
update bizoveya_private.model_credentials set enabled=true where id='platform-gemini';
insert into bizoveya_private.model_profiles(id,slug,version,revision) select profile,'execution-fixture',1,1 from ex;
insert into bizoveya_private.model_profile_versions(profile_id,version,document,reason) select profile,1,'{"name":"Fixture Gemini","provider":"gemini","credentialRef":"platform-gemini","modelId":"fixture-model","tier":"economical","maxOutputTokens":1500,"dailyBudgetCents":100}','Synthetic stage fixture' from ex;
insert into bizoveya_private.model_profile_checks(profile_id,version,credential_id,credential_version) select profile,1,'platform-gemini',1 from ex;
insert into bizoveya_private.model_test_runs(id,profile_id,profile_version,credential_id,credential_version,claim,status,result_code,input_tokens,output_tokens,reason,finished_at) select test_run,profile,1,'platform-gemini',1,gen_random_uuid(),'passed','response_matched',20,7,'Synthetic connectivity evidence',clock_timestamp() from ex;
insert into bizoveya_private.spending_policies(profile_id,version,profile_version,document,reason) select profile,1,1,jsonb_build_object('enabled',true,'inputRateMicros',0,'outputRateMicros',0,'requestFeeMicros',0,'dailyLimitMicros',10000,'runLimitMicros',10000,'validUntil',clock_timestamp()+interval '7 days','source','https://example.com/fictional-pricing','reviewed',true),'Synthetic reviewed prices' from ex;
update bizoveya_private.agent_versions set document=jsonb_set(document,'{modelTier}','"economical"') where version=1 and agent_id in(select id from bizoveya_private.agent_definitions where kind in('coordinator','content','quality'));
update bizoveya_private.agent_definitions set preview_version=1 where kind in('coordinator','content','quality');
insert into bizoveya_private.agent_checks(agent_id,version) select id,1 from bizoveya_private.agent_definitions where kind in('coordinator','content','quality') on conflict do nothing;
insert into bizoveya_private.agent_model_bindings(agent_id,agent_version,profile_id,profile_version,credential_version,test_id,revision,enabled,reason) select a.id,1,e.profile,1,1,e.test_run,1,true,'Synthetic generation binding' from bizoveya_private.agent_definitions a cross join ex e where a.kind in('coordinator','content','quality');
create temporary table ert as select jsonb_build_object('enabled',true,'agents',(select jsonb_agg(jsonb_build_object('kind',kind,'agentId',id,'agentVersion',1) order by kind) from bizoveya_private.agent_definitions)) as document;
grant all on ert to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from ex),true);
select public.bz_save_site_agent_roster(w,s,jsonb_build_object('document',ert.document,'expectedVersion',0,'reason','Enable reviewed execution fixture.','reviewed',true)) from ex,ert;
-- Three independent reviewed requests/runs exercise distinct recovery outcomes.
select public.bz_agency_command(w,s,jsonb_build_object('action','request','id',r1,'instruction','Prepare first private draft.','channels',jsonb_build_array('blog'),'reviewed',true,'inputMode','text')) from ex;
select public.bz_handoff_agency_campaign(w,s,jsonb_build_object('id',r1,'campaignId',c1,'expectedVersion',1,'title','Safe resume fixture','reviewed',true)) from ex;
select public.bz_prepare_agency_generation(w,s,jsonb_build_object('id',r1,'runId',g1,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)) from ex;
select public.bz_agency_command(w,s,jsonb_build_object('action','request','id',r2,'instruction','Prepare second private draft.','channels',jsonb_build_array('pinterest'),'reviewed',true,'inputMode','text')) from ex;
select public.bz_handoff_agency_campaign(w,s,jsonb_build_object('id',r2,'campaignId',c2,'expectedVersion',1,'title','Unstarted cancellation fixture','reviewed',true)) from ex;
select public.bz_prepare_agency_generation(w,s,jsonb_build_object('id',r2,'runId',g2,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)) from ex;
select public.bz_agency_command(w,s,jsonb_build_object('action','request','id',r3,'instruction','Prepare third private draft.','channels',jsonb_build_array('linkedin'),'reviewed',true,'inputMode','text')) from ex;
select public.bz_handoff_agency_campaign(w,s,jsonb_build_object('id',r3,'campaignId',c3,'expectedVersion',1,'title','Started marker fixture','reviewed',true)) from ex;
select public.bz_prepare_agency_generation(w,s,jsonb_build_object('id',r3,'runId',g3,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)) from ex;
reset role;
select bizoveya_private.set_platform_admin(owner_id,true,'fixture','Synthetic recovery admin') from ex;
set local role authenticated;select set_config('request.jwt.claims','{"aal":"aal2"}',true);
-- Authorization creates durable running state. An expired dispatch with no stage is safe to resume.
select public.bz_admin_authorize_generation(g1,claim1,'Authorize synthetic safe resume.',true) from ex;
select pg_temp.exexpect(format('select public.bz_admin_authorize_generation(%L,%L,%L,true)',g1,gen_random_uuid(),'Duplicate active authorization'),'bz_generation_busy') from ex;
reset role;update bizoveya_private.generation_dispatches set expires_at=statement_timestamp()-interval '1 second' where generation_id=(select g1 from ex);
set local role authenticated;
select pg_temp.exexpect(format('select public.bz_admin_authorize_generation(%L,%L,%L,true)',g1,gen_random_uuid(),'Bypass required recovery'),'bz_agency_execution_blocked') from ex;
select public.bz_admin_reconcile_agency_execution(g1,2,'Inspect expired dispatch with no stage.',true) from ex;
select pg_temp.exexpect(format('select public.bz_admin_reconcile_agency_execution(%L,2,%L,true)',g1,'Stale recovery tab'),'bz_conflict') from ex;
select public.bz_admin_authorize_generation(g1,claim1,'Resume only after safe checkpoint.',true) from ex;
-- An unstarted reserved stage is cancelled at zero and the run becomes failed.
select public.bz_admin_authorize_generation(g2,claim2,'Authorize unstarted reservation fixture.',true) from ex;
reset role;set local role service_role;
select public.bz_claim_campaign_generation_stage(g2,gen_random_uuid(),'coordinator',claim3,owner_id) from ex;
reset role;update bizoveya_private.generation_dispatches set expires_at=statement_timestamp()-interval '1 second' where generation_id=(select g2 from ex);
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from ex),true);select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select public.bz_admin_reconcile_agency_execution(g2,2,'Cancel only the unstarted expired reservation.',true) from ex;
-- A committed provider-start marker is never cancelled or retried by reconciliation.
select public.bz_admin_authorize_generation(g3,claim3,'Authorize started-marker fixture.',true) from ex;
reset role;set local role service_role;
create temporary table started_stage as select gen_random_uuid() id,gen_random_uuid() claim;grant all on started_stage to service_role,authenticated;
select public.bz_claim_campaign_generation_stage(g3,started_stage.id,'coordinator',started_stage.claim,owner_id) from ex,started_stage;
select public.bz_record_generation_request(started_stage.id,started_stage.claim,'{"runtimeVersion":"draft-runtime-v1-ai7.0.127","instructions":"Synthetic only","prompt":"No provider call","outputSchema":"coordinator","maxOutputTokens":100}') from started_stage;
reset role;update bizoveya_private.generation_dispatches set expires_at=statement_timestamp()-interval '1 second' where generation_id=(select g3 from ex);
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from ex),true);select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select public.bz_admin_reconcile_agency_execution(g3,2,'Preserve the uncertain provider-start marker.',true) from ex;
select pg_temp.exexpect(format('select public.bz_admin_authorize_generation(%L,%L,%L,true)',g3,gen_random_uuid(),'Unsafe retry attempt'),'bz_agency_execution_blocked') from ex;
reset role;
do $$begin
 if (select state from bizoveya_private.agency_execution_tasks where run_id=(select g1 from ex))<>'running' then raise exception 'Safe resume was not reauthorized';end if;
 if (select count(*) from bizoveya_private.agency_execution_task_events where record_id=(select r1 from ex))<>4 then raise exception 'Safe resume history mismatch';end if;
 if (select state from bizoveya_private.agency_execution_tasks where run_id=(select g2 from ex))<>'failed' or (select spending_state from bizoveya_private.generation_stage_runs where generation_run_id=(select g2 from ex))<>'settled' or (select charged_micros from bizoveya_private.generation_stage_runs where generation_run_id=(select g2 from ex))<>0 then raise exception 'Unstarted cancellation was not safely settled';end if;
 if (select state from bizoveya_private.agency_execution_tasks where run_id=(select g3 from ex))<>'recovery_required' or (select provider_started_at from bizoveya_private.generation_stage_runs where generation_run_id=(select g3 from ex)) is null then raise exception 'Provider-start marker was not preserved';end if;
 if (select count(*) from bizoveya_private.generation_stage_runs where generation_run_id=(select g3 from ex))<>1 then raise exception 'Reconciliation duplicated provider work';end if;
end;$$;
select pg_temp.exexpect('update bizoveya_private.agency_execution_task_events set reason=''Forged''','bz_immutable_agency_handoff');
set local role authenticated;select set_config('request.jwt.claim.sub',(select outsider::text from ex),true);select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select pg_temp.exexpect(format('select public.bz_admin_reconcile_agency_execution(%L,3,%L,true)',g3,'Outsider recovery attempt'),'bz_admin_forbidden') from ex;
select pg_temp.exexpect('select * from bizoveya_private.agency_execution_tasks','permission denied');
reset role;
delete from public.bizoveya_sites where id=(select s from ex);
do $$begin if exists(select 1 from bizoveya_private.agency_execution_tasks) or exists(select 1 from bizoveya_private.agency_execution_task_events) then raise exception 'Execution-task site cascade failed';end if;end;$$;
rollback;
